def solve_partition(n):
    """
    Attempts to find a partition of {1, ..., 2n} into n pairs 
    whose differences are {1, ..., n} using backtracking.
    """
    nums = set(range(1, 2 * n + 1))
    diffs = set(range(1, n + 1))

    def backtrack():
        if not diffs:
            return True  # All differences used successfully

        # Find the smallest available number to anchor the next pairing
        try:
            start_num = min(nums)
        except ValueError:
            # This should only happen if the sets are mismanaged, but handles empty case
            return False

        # Iterate through unused differences
        for d in list(diffs):
            target_num = start_num + d

            if target_num in nums:
                # Try this pairing (start_num, target_num) with difference d

                # 1. Make moves
                new_nums = nums - {start_num, target_num}
                new_diffs = diffs - {d}

                # 2. Recurse
                if solve_partition.__closure__[0].__self__.backtrack(new_nums, new_diffs):
                    return True

                # 3. Backtrack (implicitly done by scope/not modifying originals)

        return False

    # Helper wrapper function to manage state passing in recursion
    # Due to Python scope limitations in simple recursive calls, we pass state explicitly
    def recursive_solve(current_nums, current_diffs):
        if not current_diffs:
            return True

        try:
            start_num = min(current_nums)
        except ValueError:
            return False # Should not happen if diffs is not empty

        for d in list(current_diffs):
            target_num = start_num + d

            if target_num in current_nums:

                new_nums = current_nums - {start_num, target_num}
                new_diffs = current_diffs - {d}

                if recursive_solve(new_nums, new_diffs):
                    return True
        return False

    return recursive_solve(nums, diffs)

